return $input.all().map(({ json }) => {
  const cuerpo = json.plantilla_cuerpo || 'Feliz cumpleanos, {{nombres}}! Todo el equipo del gimnasio te desea un gran dia.';
  const vars = { nombres: json.nombres || '', apellidos: json.apellidos || '', plan: '', fecha_fin: '', dias_restantes: '', monto: '' };
  const texto = String(cuerpo).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => (vars[k] ?? ''));
  let numero = String(json.telefono || '').replace(/\D/g, '');
  if (numero.length === 9) numero = '51' + numero;
  return { json: { socio_id: json.socio_id, clave: 'cumpleanos', numero, texto } };
}).filter((i) => i.json.numero);

const esc = (s) => String(s ?? '').replace(/'/g, "''");
return $('Render').all().map(({ json: r }) => {
  const sql = `INSERT INTO mensajes_enviados (socio_id, telefono, canal, plantilla_clave, contenido, estado, enviado_en, referencia_tipo, referencia_id, periodo) VALUES ('${esc(r.socio_id)}', '${esc(r.numero)}', 'whatsapp', 'cumpleanos', '${esc(r.texto)}', 'enviado', now(), 'cumpleanos', '${esc(r.socio_id)}', to_char(CURRENT_DATE, 'YYYY'))`;
  return { json: { sql } };
});
